mapper.select:
SELECT num, member_num, type, category, content, status, created_date,
target_num
FROM (
SELECT num, member_num, type, category, content, status, created_date,
target_num,
ROW_NUMBER() OVER(ORDER BY num DESC) AS row_num
FROM report
WHERE member_num = #{member_num}
) numbered_rows
WHERE row_num BETWEEN #{begin} AND #{end}

